package com.closky.rpgmod.worldgen;

import com.closky.rpgmod.boss.BossDefinition;

import javax.annotation.Nullable;
import java.util.ArrayList;
import java.util.List;

/**
 * Static description of the eight dungeons (section 5.2). The block palettes drive both the shipped templates
 * (generated by {@code tools/gen_templates.py}) and the in-game {@code /rpgmod dungeon generate_templates} command;
 * the gameplay data (level, boss, loot table) is used by commands and documentation.
 */
public final class DungeonRegistry {
    /**
     * @param walls        weighted wall block states (first entry is the primary block)
     * @param floor        weighted floor block states
     * @param light        light source state (hanging / standing)
     * @param decor        small decoration states placed sparsely on the floor
     * @param spawnerMobs  entity ids used in vanilla mob spawners
     */
    public record DungeonInfo(String id, int level, BossDefinition boss, boolean underground, List<String> walls,
                              List<String> floor, String light, List<String> decor, List<String> spawnerMobs,
                              float ruinFactor, boolean roofed) {
        public String lootTable() {
            return "rpgmod:chests/" + id;
        }
    }

    private static final List<DungeonInfo> DUNGEONS = new ArrayList<>();

    static {
        DUNGEONS.add(new DungeonInfo("catacombs_basic", 5, BossDefinition.SKELETON_KING, true,
                List.of("minecraft:stone_bricks", "minecraft:stone_bricks", "minecraft:mossy_stone_bricks", "minecraft:cracked_stone_bricks"),
                List.of("minecraft:stone_bricks", "minecraft:cobblestone", "minecraft:gravel"),
                "minecraft:soul_lantern[hanging=true]",
                List.of("minecraft:cobweb", "minecraft:skeleton_skull[rotation=4]", "minecraft:bone_block", "minecraft:brown_mushroom"),
                List.of("minecraft:skeleton", "minecraft:zombie"), 0.0F, true));
        DUNGEONS.add(new DungeonInfo("bandit_camp", 6, BossDefinition.BANDIT_CHIEF, false,
                List.of("minecraft:spruce_planks", "minecraft:spruce_log[axis=y]", "minecraft:stripped_spruce_log[axis=y]"),
                List.of("minecraft:coarse_dirt", "minecraft:dirt_path", "minecraft:spruce_planks"),
                "minecraft:torch",
                List.of("minecraft:hay_block", "minecraft:barrel[facing=up]", "minecraft:campfire[lit=true]", "minecraft:spruce_fence"),
                List.of("minecraft:pillager", "minecraft:vindicator"), 0.0F, false));
        DUNGEONS.add(new DungeonInfo("deep_mines", 7, BossDefinition.MINE_OVERSEER, true,
                List.of("minecraft:cobblestone", "minecraft:stone", "minecraft:andesite", "minecraft:coal_ore", "minecraft:iron_ore"),
                List.of("minecraft:cobblestone", "minecraft:gravel", "minecraft:stone"),
                "minecraft:lantern[hanging=true]",
                List.of("minecraft:oak_fence", "minecraft:rail", "minecraft:cobweb", "minecraft:oak_planks"),
                List.of("minecraft:cave_spider", "minecraft:zombie", "minecraft:husk"), 0.0F, true));
        DUNGEONS.add(new DungeonInfo("abandoned_manor", 8, BossDefinition.MANOR_GHOST, false,
                List.of("minecraft:dark_oak_planks", "minecraft:dark_oak_planks", "minecraft:cobblestone", "minecraft:dark_oak_log[axis=y]"),
                List.of("minecraft:dark_oak_planks", "minecraft:spruce_planks"),
                "minecraft:candle[candles=3,lit=true]",
                List.of("minecraft:cobweb", "minecraft:bookshelf", "minecraft:flower_pot", "minecraft:dark_oak_stairs[facing=north]"),
                List.of("minecraft:zombie_villager", "minecraft:witch", "minecraft:skeleton"), 0.05F, true));
        DUNGEONS.add(new DungeonInfo("labyrinth_basic", 9, BossDefinition.LABYRINTH_MINOTAUR, true,
                List.of("minecraft:deepslate_bricks", "minecraft:deepslate_bricks", "minecraft:cracked_deepslate_bricks", "minecraft:tuff"),
                List.of("minecraft:deepslate_tiles", "minecraft:deepslate_bricks"),
                "minecraft:lantern[hanging=true]",
                List.of("minecraft:cobweb", "minecraft:deepslate_brick_wall", "minecraft:glow_lichen[down=true]", "minecraft:moss_carpet"),
                List.of("minecraft:zombie", "minecraft:spider", "minecraft:cave_spider"), 0.0F, true));
        DUNGEONS.add(new DungeonInfo("underground_fortress", 10, BossDefinition.FORTRESS_LORD, true,
                List.of("minecraft:polished_deepslate", "minecraft:deepslate_tiles", "minecraft:polished_blackstone_bricks"),
                List.of("minecraft:polished_deepslate", "minecraft:deepslate_tiles"),
                "minecraft:soul_lantern[hanging=true]",
                List.of("minecraft:iron_bars", "minecraft:chain[axis=y]", "minecraft:anvil[facing=north]", "minecraft:polished_blackstone_wall"),
                List.of("minecraft:skeleton", "minecraft:zombie", "minecraft:vindicator"), 0.0F, true));
        DUNGEONS.add(new DungeonInfo("ruined_castle", 12, BossDefinition.FALLEN_KING, false,
                List.of("minecraft:stone_bricks", "minecraft:mossy_stone_bricks", "minecraft:cobblestone", "minecraft:mossy_cobblestone"),
                List.of("minecraft:stone_bricks", "minecraft:cobblestone", "minecraft:grass_block"),
                "minecraft:torch",
                List.of("minecraft:cobweb", "minecraft:vine[north=true]", "minecraft:stone_brick_slab", "minecraft:fern"),
                List.of("minecraft:skeleton", "minecraft:zombie", "minecraft:stray"), 0.12F, true));
        DUNGEONS.add(new DungeonInfo("arcane_tower", 15, BossDefinition.ARCHMAGE, false,
                List.of("minecraft:quartz_bricks", "minecraft:smooth_quartz", "minecraft:chiseled_quartz_block", "minecraft:amethyst_block"),
                List.of("minecraft:smooth_quartz", "minecraft:purpur_block"),
                "minecraft:sea_lantern",
                List.of("minecraft:bookshelf", "minecraft:enchanting_table", "minecraft:lectern[facing=north]", "minecraft:amethyst_cluster[facing=up]"),
                List.of("minecraft:witch", "minecraft:skeleton", "minecraft:blaze"), 0.0F, true));
    }

    private DungeonRegistry() {
    }

    public static List<DungeonInfo> all() {
        return DUNGEONS;
    }

    public static List<String> ids() {
        List<String> ids = new ArrayList<>();
        for (DungeonInfo info : DUNGEONS) {
            ids.add(info.id());
        }
        return ids;
    }

    @Nullable
    public static DungeonInfo get(String id) {
        for (DungeonInfo info : DUNGEONS) {
            if (info.id().equals(id)) {
                return info;
            }
        }
        return null;
    }
}
